# glyphs.py -- baked 1-bit glyph bitmaps at 64px (Noto Serif/Sans).
# Generated by /tmp/bake_glyphs.py on this VM from local TTFs.
# Pure data: no imaging library, no system fonts at runtime. Deterministic.
import base64
import json
import zlib


def _load():
    raw = zlib.decompress(base64.b64decode(_BLOB))
    data = json.loads(raw.decode('utf-8'))
    for style in data['styles'].values():
        for rec in style.values():
            rec[5] = base64.b64decode(rec[5]) if rec[5] else b''
    return data


_BLOB = ''


GLYPHS = _load()
